package com.leetcode.backend.model;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;
@Entity @Table(name="learning_path_items",uniqueConstraints=@UniqueConstraint(columnNames={"section_id","problem_id"}),indexes=@Index(name="idx_path_item_section_position",columnList="section_id,position"))public class LearningPathItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@JsonIgnore @ManyToOne(optional=false)@JoinColumn(name="section_id")private LearningPathSection section;@ManyToOne(optional=false)@JoinColumn(name="problem_id")private Problem problem;private int position;public Long getId(){return id;}public LearningPathSection getSection(){return section;}public void setSection(LearningPathSection v){section=v;}public Problem getProblem(){return problem;}public void setProblem(Problem v){problem=v;}public int getPosition(){return position;}public void setPosition(int v){position=v;}}
